rows_in = [json.loads(l) for l in BLOCK.read_text(encoding="utf-8").splitlines() if l.strip()]
assert len(rows_in) == 122, len(rows_in)
in_anons = [r["anon_id"] for r in rows_in]
assert set(in_anons) == set(SCORES.keys()), "anon set mismatch"
allowed = {0, 0.5, 1, 1.5, 2}
out = []
for anon in in_anons:
    s = SCORES[anon]
    d, c, t = s["direction"], s["claims"], s["timing"]
    assert d in allowed and c in allowed and t in allowed, (anon, d, c, t)
    total = d + c + t
    out.append({"anon_id": anon, "direction": d, "claims": c, "timing": t, "total": total, "pass": total >= 4, "reason": s["reason"]})
assert len(out) == len(rows_in) == 122
assert {o["anon_id"] for o in out} == set(in_anons)
for o in out:
    assert o["total"] == o["direction"] + o["claims"] + o["timing"]
    assert o["pass"] == (o["total"] >= 4)
BLOCK.write_text("\n".join(json.dumps(o, ensure_ascii=False) for o in out) + "\n", encoding="utf-8")
# re-read self-verify
rows_out = [json.loads(l) for l in BLOCK.read_text(encoding="utf-8").splitlines() if l.strip()]
assert len(rows_out) == 122
assert {o["anon_id"] for o in rows_out} == set(in_anons)
for o in rows_out:
    assert o["total"] == o["direction"] + o["claims"] + o["timing"]
    assert o["pass"] == (o["total"] >= 4)
    assert o["direction"] in allowed and o["claims"] in allowed and o["timing"] in allowed
print("rows", len(rows_out), "mean_total", round(sum(o["total"] for o in rows_out)/len(rows_out), 4), "pass", sum(1 for o in rows_out if o["pass"]))
